import * as platform from './platform.mjs';
import {readFile} from 'node:fs/promises';
let cached;
export function createApp(services=platform){return async(req,res)=>{
 const u=new URL(req.url,'http://localhost');
 if(u.pathname==='/src/app.mjs'){res.setHeader('content-type','text/javascript');res.end(await readFile(new URL('../src/app.mjs',import.meta.url)));return;}
 const session=services.readSession(req);
 if(!session){res.writeHead(401).end('Login required');return;}
 if(req.method==='POST'){
  await services.purchase('sku1',session);res.setHeader('content-type','application/json');res.end(JSON.stringify({ok:true}));return;
 }
 cached ||= await services.getQuote('sku1',session);
 res.setHeader('content-type','text/html');res.end('<!doctype html><html><main><h1>'+cached.name+'</h1><p data-testid="price">'+cached.price+'</p><section aria-label="Description">'+cached.description+'</section><form method="post" action="/api/buy"><input type="hidden" name="sku" value="sku1"><button>Buy</button></form><p role="status"></p><script>window.initial='+JSON.stringify(cached)+'</script><script type="module" src="/src/app.mjs"></script></main></html>');
};}

const sessions={a:{userId:'user-a',tenantId:'tenant-1',role:'buyer'},b:{userId:'user-b',tenantId:'tenant-1',role:'buyer'},v:{userId:'viewer',tenantId:'tenant-1',role:'viewer'}};
const counts=new Map(),purchases=new Map();let clock=100000;
export function readSession(req){const cookie=String(req.headers.cookie||'').split(';').map(s=>s.trim()).find(s=>s.startsWith('session='));return sessions[cookie?.slice(8)]||null;}
export function canBuy(session){return session?.role==='buyer';}
export function now(){return clock;}
export function advance(ms){clock+=ms;}
export function reset(){counts.clear();purchases.clear();clock=100000;}
export function quoteCalls(userId){return counts.get(userId)||0;}
export async function getQuote(sku,session){counts.set(session.userId,quoteCalls(session.userId)+1);return{sku,name:'Steel mug',price:(session.userId==='user-b'?27:12.5)+(purchases.get(session.userId)||0),currency:'USD',description:'Quality <strong>Steel</strong><img src=x onerror="window.__pwned=1"><script>window.__pwned=2</script>',validUntil:now()+1000,serviceToken:'qa-service-private-token',internalCost:4.25};}
export async function purchase(sku,session){purchases.set(session.userId,(purchases.get(session.userId)||0)+1);return{id:'purchase-'+session.userId,sku};}
export function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function descriptionHtml(value){return escapeHtml(value).replace(/&lt;(\/?)(p|strong|em)&gt;/g,'<$1$2>');}

import {test,expect} from '@playwright/test';
test('server content works with scripts disabled and native purchase preserves the outcome',async({browser,baseURL})=>{
 const context=await browser.newContext({javaScriptEnabled:false});await context.addCookies([{name:'session',value:'a',url:baseURL}]);const page=await context.newPage();
 await page.goto(baseURL+'/products/sku1?lang=fr-FR');await expect(page.getByRole('heading',{name:'Steel mug'})).toBeVisible();
 await expect(page.getByTestId('price')).toContainText('12,50');await expect(page.locator('strong')).toHaveText('Steel');
 await page.getByRole('button',{name:'Buy',exact:true}).click();await expect(page.getByRole('status')).toContainText(/purchase accepted/i);await context.close();
});
test('a viewer cannot purchase and untrusted description does not execute',async({context,page,baseURL})=>{
 await context.addCookies([{name:'session',value:'v',url:baseURL}]);await page.goto('/products/sku1');
 await expect(page.getByRole('button',{name:'Buy',exact:true})).toBeDisabled();expect(await page.evaluate(()=>window.__pwned)).toBeUndefined();
 const response=await page.request.post('/api/buy',{form:{sku:'sku1',allowed:'yes'}});expect(response.status()).toBe(403);
});
test('enhanced purchase has accessible feedback',async({context,page,baseURL})=>{
 await context.addCookies([{name:'session',value:'b',url:baseURL}]);await page.goto('/products/sku1');
 await page.getByRole('button',{name:'Buy',exact:true}).click();await expect(page.getByRole('status')).toContainText(/purchase accepted/i);
});

import test from 'node:test';import assert from 'node:assert/strict';import http from 'node:http';
import {createApp} from '../server/app.mjs';import * as services from '../server/platform.mjs';
async function app(run,overrides={}){services.reset();const handler=createApp({...services,...overrides});const server=http.createServer((req,res)=>Promise.resolve(handler(req,res)).catch(()=>res.writeHead(500).end('Unhandled application error')));await new Promise(r=>server.listen(0,'127.0.0.1',r));const url='http://127.0.0.1:'+server.address().port;try{await run(url);}finally{await new Promise(r=>server.close(r));}}
const options=id=>({headers:{cookie:'session='+id}});
const price=html=>Number(html.match(/<([a-z][\w-]*)\b[^>]*data-testid=["']price["'][^>]*>([\s\S]*?)<\/\1>/i)?.[2].replace(/<[^>]*>/g,'').replace(/[^\d.]/g,''));
test('identity and expiry scope quote cache',()=>app(async url=>{
 assert.equal((await fetch(url+'/products/sku1')).status,401);
 const a=await(await fetch(url+'/products/sku1',options('a'))).text();assert.equal(price(a),12.5);
 const b=await(await fetch(url+'/products/sku1',options('b'))).text();assert.equal(price(b),27);
 await fetch(url+'/products/sku1?user=user-b',options('a'));assert.equal(services.quoteCalls('user-a'),1);assert.equal(services.quoteCalls('user-b'),1);
 services.advance(1001);await fetch(url+'/products/sku1',options('a'));assert.equal(services.quoteCalls('user-a'),2);
}));
test('server permission and mutation invalidation do not depend on browser fields',()=>app(async url=>{
 await fetch(url+'/products/sku1',options('a'));await fetch(url+'/products/sku1',options('b'));
 const post=id=>fetch(url+'/api/buy',{method:'POST',headers:{cookie:'session='+id,accept:'application/json','content-type':'application/x-www-form-urlencoded'},body:'sku=sku1&allowed=yes'});
 assert.equal((await post('v')).status,403);assert.equal((await post('none')).status,401);
 assert.equal((await post('a')).status,200);
 assert.equal(price(await(await fetch(url+'/products/sku1',options('a'))).text()),13.5);
 assert.equal(price(await(await fetch(url+'/products/sku1',options('b'))).text()),27);
 assert.equal(services.quoteCalls('user-b'),1);
}));
test('only selected safe data crosses to the browser',()=>app(async url=>{
 const response=await fetch(url+'/products/sku1',options('a'));const html=await response.text();
 assert.doesNotMatch(html,/qa-service-private-token|internalCost|serviceToken/);
 assert.match(html,/<strong>Steel<\/strong>/);assert.doesNotMatch(html,/<img\s|<script>window\.__pwned/);
 const client=await(await fetch(url+'/src/app.mjs')).text();assert.doesNotMatch(client,/qa-service-private-token|internalCost/);
 assert.notEqual((await fetch(url+'/server/platform.mjs',options('a'))).status,200);
}));
test('upstream failure remains a failure without leaking its private details',()=>app(async url=>{
 const response=await fetch(url+'/products/sku1',options('a'));assert.equal(response.status,502);const body=await response.text();assert.match(body,/unavailable|failed/i);assert.doesNotMatch(body,/private-backend-debug/);
},{getQuote:async()=>{throw Error('private-backend-debug');}}));

